import re

def parse_ocorrencia(texto: str) -> dict:
    padrao = r'BO nº (\d+) de (\d{4}) - Delegacia: (.+)'
    match = re.search(padrao, texto)
    if match:
        numero_bo = match.group(1)
        ano = match.group(2)
        delegacia = match.group(3)
        return {'numero_bo': numero_bo, 'ano': ano, 'delegacia': delegacia}
    else:
        return {}
```

